index 0000000..3160b55
--- /dev/null
+++ b/encryption/config.go
@@ -0,0 +1,153 @@
+package encryption
+
+import (
+	"crypto/pbkdf2"
+	"crypto/sha256"
+	"encoding/base64"
+	"errors"
+	"fmt"
+	"os"
+	"strings"
+)
+
+const (
+	KeySourceEnv     = "env"
+	KeySourceFile    = "file"
+	KeySourceLiteral = "literal"
+	KeySourceDerive  = "derive"
+
+	MinSaltSize      = 16
+	deriveIterations = 600_000
+)
+
+// Config describes whether a job is encrypted and where its key comes from.
+type Config struct {
+	Enabled    bool   `yaml:"enabled"`
+	KeySource  string `yaml:"keysource"`
+	KeyEnvVar  string `yaml:"keyenvvar"`
+	KeyFile    string `yaml:"keyfile"`
+	Key        string `yaml:"key"`
+	Passphrase string `yaml:"passphrase"`
+	Salt       string `yaml:"salt"`
+}
+
+func (cfg Config) source() string {
+	return strings.ToLower(strings.TrimSpace(cfg.KeySource))
+}
+
+// Validate checks the configuration. Disabled configs are always valid.
+func (cfg Config) Validate() error {
+	if !cfg.Enabled {
+		return nil
+	}
+
+	return cfg.validateSource()
+}
+
+func (cfg Config) validateSource() error {
+	type field struct {
+		name  string
+		value string
+	}
+
+	envVar := field{"keyenvvar", cfg.KeyEnvVar}
+	keyFile := field{"keyfile", cfg.KeyFile}
+	key := field{"key", cfg.Key}
+	passphrase := field{"passphrase", cfg.Passphrase}
+	salt := field{"salt", cfg.Salt}
+
+	var required, forbidden []field
+
+	switch cfg.source() {
+	case "":
+		return errors.New("encryption key source is required")
+	case KeySourceEnv:
+		required = []field{envVar}
+		forbidden = []field{keyFile, key, passphrase, salt}
+	case KeySourceFile:
+		required = []field{keyFile}
+		forbidden = []field{envVar, key, passphrase, salt}
+	case KeySourceLiteral:
+		required = []field{key}
+		forbidden = []field{envVar, keyFile, passphrase, salt}
+	case KeySourceDerive:
+		required = []field{passphrase, salt}
+		forbidden = []field{envVar, keyFile, key}
+	default:
+		return fmt.Errorf("unsupported encryption key source %q, must be one of: env, file, literal, derive", cfg.KeySource)
+	}
+
+	var errs error
+	for _, f := range required {
+		if strings.TrimSpace(f.value) == "" {
+			errs = errors.Join(errs, fmt.Errorf("encryption key source %q requires %s", cfg.source(), f.name))
+		}
+	}
+
+	for _, f := range forbidden {
+		if strings.TrimSpace(f.value) != "" {
+			errs = errors.Join(errs, fmt.Errorf("encryption %s is mutually exclusive with key source %q", f.name, cfg.source()))
+		}
+	}
+
+	return errs
+}
+
+// LoadKey loads the 32-byte encryption key described by cfg.
+func LoadKey(cfg Config) ([]byte, error) {
+	if err := cfg.validateSource(); err != nil {
+		return nil, err
+	}
+
+	switch cfg.source() {
+	case KeySourceEnv:
+		value, ok := os.LookupEnv(cfg.KeyEnvVar)
+		if !ok {
+			return nil, fmt.Errorf("encryption key env var %s is not set", cfg.KeyEnvVar)
+		}
+		return decodeKey(value, "env var "+cfg.KeyEnvVar)
+	case KeySourceFile:
+		content, err := os.ReadFile(cfg.KeyFile)
+		if err != nil {
+			return nil, fmt.Errorf("could not read encryption key file: %w", err)
+		}
+		return decodeKey(string(content), "file "+cfg.KeyFile)
+	case KeySourceLiteral:
+		return decodeKey(cfg.Key, "literal")
+	case KeySourceDerive:
+		return deriveKey(cfg.Passphrase, cfg.Salt)
+	}
+
+	// unreachable: validateSource rejects unknown sources
+	return nil, fmt.Errorf("unsupported encryption key source %q", cfg.KeySource)
+}
+
+func decodeKey(encoded, origin string) ([]byte, error) {
+	key, err := base64.StdEncoding.DecodeString(strings.TrimSpace(encoded))
+	if err != nil {
+		return nil, fmt.Errorf("%w: encryption key from %s is not valid base64: %v", ErrInvalidKey, origin, err)
+	}
+
+	if len(key) != KeySize {
+		return nil, fmt.Errorf("%w: encryption key from %s must decode to %d bytes, got %d", ErrInvalidKey, origin, KeySize, len(key))
+	}
+
+	return key, nil
+}
+
+func deriveKey(passphrase, encodedSalt string) ([]byte, error) {
+	if passphrase == "" {
+		return nil, errors.New("encryption key derivation requires a non-empty passphrase")
+	}
+
+	salt, err := base64.StdEncoding.DecodeString(strings.TrimSpace(encodedSalt))
+	if err != nil {
+		return nil, fmt.Errorf("encryption key derivation salt is not valid base64: %w", err)
+	}
+
+	if len(salt) < MinSaltSize {
+		return nil, fmt.Errorf("encryption key derivation salt must be at least %d bytes, got %d", MinSaltSize, len(salt))
+	}
+
+	return pbkdf2.Key(sha256.New, passphrase, salt, deriveIterations, KeySize)
+}
diff --git a/encryption/config_test.go b/encryption/config_test.go
