+++ b/encryption/config_test.go
@@ -0,0 +1,110 @@
+package encryption
+
+import (
+	"bytes"
+	"encoding/base64"
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/stretchr/testify/assert"
+	"github.com/stretchr/testify/require"
+)
+
+var (
+	validKey  = base64.StdEncoding.EncodeToString(bytes.Repeat([]byte{7}, 32))
+	validSalt = base64.StdEncoding.EncodeToString(bytes.Repeat([]byte{1}, 16))
+)
+
+func TestValidate(t *testing.T) {
+	cases := []struct {
+		name   string
+		cfg    Config
+		errMsg string
+	}{
+		{"disabled", Config{KeySource: "bogus", Key: "x", KeyFile: "y"}, ""},
+		{"empty source", Config{Enabled: true}, "source"},
+		{"unsupported source", Config{Enabled: true, KeySource: "vault"}, "unsupported"},
+		{"env", Config{Enabled: true, KeySource: "env", KeyEnvVar: "K"}, ""},
+		{"env case insensitive", Config{Enabled: true, KeySource: "ENV", KeyEnvVar: "K"}, ""},
+		{"env missing", Config{Enabled: true, KeySource: "env"}, "keyenvvar"},
+		{"env with key", Config{Enabled: true, KeySource: "env", KeyEnvVar: "K", Key: validKey}, "mutually exclusive"},
+		{"file", Config{Enabled: true, KeySource: "File", KeyFile: "/k"}, ""},
+		{"file missing", Config{Enabled: true, KeySource: "file"}, "keyfile"},
+		{"file with env", Config{Enabled: true, KeySource: "file", KeyFile: "/k", KeyEnvVar: "K"}, "mutually exclusive"},
+		{"literal", Config{Enabled: true, KeySource: "literal", Key: validKey}, ""},
+		{"literal missing", Config{Enabled: true, KeySource: "literal"}, "key"},
+		{"literal with passphrase", Config{Enabled: true, KeySource: "literal", Key: validKey, Passphrase: "p"}, "mutually exclusive"},
+		{"derive", Config{Enabled: true, KeySource: "derive", Passphrase: "p", Salt: validSalt}, ""},
+		{"derive missing salt", Config{Enabled: true, KeySource: "derive", Passphrase: "p"}, "salt"},
+		{"derive missing passphrase", Config{Enabled: true, KeySource: "derive", Salt: validSalt}, "passphrase"},
+		{"derive with file", Config{Enabled: true, KeySource: "derive", Passphrase: "p", Salt: validSalt, KeyFile: "/k"}, "mutually exclusive"},
+	}
+
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			err := tc.cfg.Validate()
+			if tc.errMsg == "" {
+				assert.NoError(t, err)
+			} else {
+				assert.ErrorContains(t, err, tc.errMsg)
+			}
+		})
+	}
+}
+
+func TestLoadKeyEnv(t *testing.T) {
+	t.Setenv("ONEDUMP_TEST_KEY", validKey)
+	key, err := LoadKey(Config{Enabled: true, KeySource: "env", KeyEnvVar: "ONEDUMP_TEST_KEY"})
+	require.NoError(t, err)
+	assert.Len(t, key, 32)
+
+	_, err = LoadKey(Config{Enabled: true, KeySource: "env", KeyEnvVar: "ONEDUMP_TEST_KEY_UNSET"})
+	assert.ErrorContains(t, err, "not set")
+
+	t.Setenv("ONEDUMP_TEST_KEY", base64.StdEncoding.EncodeToString([]byte("short")))
+	_, err = LoadKey(Config{Enabled: true, KeySource: "env", KeyEnvVar: "ONEDUMP_TEST_KEY"})
+	assert.ErrorIs(t, err, ErrInvalidKey)
+}
+
+func TestLoadKeyFile(t *testing.T) {
+	path := filepath.Join(t.TempDir(), "key")
+	require.NoError(t, os.WriteFile(path, []byte("  "+validKey+"\n"), 0600))
+
+	key, err := LoadKey(Config{Enabled: true, KeySource: "file", KeyFile: path})
+	require.NoError(t, err)
+	assert.Equal(t, bytes.Repeat([]byte{7}, 32), key)
+
+	_, err = LoadKey(Config{Enabled: true, KeySource: "file", KeyFile: path + ".missing"})
+	assert.Error(t, err)
+}
+
+func TestLoadKeyLiteral(t *testing.T) {
+	key, err := LoadKey(Config{Enabled: true, KeySource: "literal", Key: validKey})
+	require.NoError(t, err)
+	assert.Equal(t, bytes.Repeat([]byte{7}, 32), key)
+
+	_, err = LoadKey(Config{Enabled: true, KeySource: "literal", Key: "!!!not base64"})
+	assert.ErrorIs(t, err, ErrInvalidKey)
+}
+
+func TestLoadKeyDerive(t *testing.T) {
+	cfg := Config{Enabled: true, KeySource: "derive", Passphrase: "secret", Salt: validSalt}
+	k1, err := LoadKey(cfg)
+	require.NoError(t, err)
+	k2, err := LoadKey(cfg)
+	require.NoError(t, err)
+	assert.Len(t, k1, 32)
+	assert.Equal(t, k1, k2)
+
+	cfg.Passphrase = "other"
+	k3, err := LoadKey(cfg)
+	require.NoError(t, err)
+	assert.NotEqual(t, k1, k3)
+
+	_, err = LoadKey(Config{Enabled: true, KeySource: "derive", Passphrase: "secret", Salt: base64.StdEncoding.EncodeToString(make([]byte, 15))})
+	assert.ErrorContains(t, err, "salt")
+
+	_, err = LoadKey(Config{Enabled: true, KeySource: "derive", Passphrase: "", Salt: validSalt})
+	assert.ErrorContains(t, err, "passphrase")
+}
