index 0000000..d4e5d89
--- /dev/null
+++ b/encryption/encryption.go
@@ -0,0 +1,325 @@
+// Package encryption provides AES-256-GCM streaming encryption for dump files.
+//
+// Stream format:
+//
+//	header   : 0x4F 0x44 (magic) | 0x01 (version)
+//	chunk(s) : 4-byte big-endian length | 12-byte nonce | ciphertext + 16-byte tag
+//	sentinel : 4 zero bytes
+//	trailer  : 32-byte HMAC-SHA256 over all bytes between header and sentinel
+package encryption
+
+import (
+	"crypto/aes"
+	"crypto/cipher"
+	"crypto/hmac"
+	"crypto/rand"
+	"crypto/sha256"
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"hash"
+	"io"
+)
+
+const (
+	KeySize        = 32
+	ChunkSize      = 64 * 1024
+	Version   byte = 0x01
+
+	headerSize = 3
+	lengthSize = 4
+	nonceSize  = 12
+	tagSize    = 16
+	macSize    = sha256.Size
+
+	minChunkLen = nonceSize + tagSize
+	maxChunkLen = nonceSize + ChunkSize + tagSize
+)
+
+var (
+	ErrInvalidKey = errors.New("invalid encryption key")
+
+	magic = [2]byte{0x4F, 0x44}
+)
+
+type Encryptor struct {
+	key  []byte
+	aead cipher.AEAD
+}
+
+// NewEncryptor creates an AES-256-GCM encryptor. The key must be exactly 32 bytes.
+func NewEncryptor(key []byte) (*Encryptor, error) {
+	aead, err := newAEAD(key)
+	if err != nil {
+		return nil, err
+	}
+
+	k := make([]byte, len(key))
+	copy(k, key)
+
+	return &Encryptor{key: k, aead: aead}, nil
+}
+
+func newAEAD(key []byte) (cipher.AEAD, error) {
+	if len(key) != KeySize {
+		return nil, fmt.Errorf("%w: key must be %d bytes, got %d", ErrInvalidKey, KeySize, len(key))
+	}
+
+	block, err := aes.NewCipher(key)
+	if err != nil {
+		return nil, fmt.Errorf("%w: %v", ErrInvalidKey, err)
+	}
+
+	return cipher.NewGCM(block)
+}
+
+// EncryptWriter returns a WriteCloser that encrypts everything written to it into w.
+// Close must be called to flush the final chunk and write the integrity trailer.
+// Close does not close w.
+func (e *Encryptor) EncryptWriter(w io.Writer) io.WriteCloser {
+	return &encryptWriter{
+		w:    w,
+		aead: e.aead,
+		mac:  hmac.New(sha256.New, e.key),
+		buf:  make([]byte, 0, ChunkSize),
+	}
+}
+
+type encryptWriter struct {
+	w             io.Writer
+	aead          cipher.AEAD
+	mac           hash.Hash
+	buf           []byte
+	headerWritten bool
+	closed        bool
+	err           error
+}
+
+func (ew *encryptWriter) writeHeader() error {
+	if ew.headerWritten {
+		return nil
+	}
+	ew.headerWritten = true
+
+	_, err := ew.w.Write([]byte{magic[0], magic[1], Version})
+	return err
+}
+
+func (ew *encryptWriter) Write(p []byte) (int, error) {
+	if ew.closed {
+		return 0, errors.New("encryption: write to closed writer")
+	}
+	if ew.err != nil {
+		return 0, ew.err
+	}
+
+	if err := ew.writeHeader(); err != nil {
+		ew.err = err
+		return 0, err
+	}
+
+	written := 0
+	for len(p) > 0 {
+		n := min(ChunkSize-len(ew.buf), len(p))
+		ew.buf = append(ew.buf, p[:n]...)
+		p = p[n:]
+		written += n
+
+		if len(ew.buf) == ChunkSize {
+			if err := ew.flushChunk(); err != nil {
+				ew.err = err
+				return written, err
+			}
+		}
+	}
+
+	return written, nil
+}
+
+func (ew *encryptWriter) flushChunk() error {
+	if len(ew.buf) == 0 {
+		return nil
+	}
+
+	nonce := make([]byte, nonceSize)
+	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
+		return fmt.Errorf("encryption: could not generate nonce: %w", err)
+	}
+
+	out := make([]byte, lengthSize, lengthSize+nonceSize+len(ew.buf)+tagSize)
+	out = append(out, nonce...)
+	out = ew.aead.Seal(out, nonce, ew.buf, nil)
+	binary.BigEndian.PutUint32(out[:lengthSize], uint32(len(out)-lengthSize))
+
+	ew.mac.Write(out)
+	ew.buf = ew.buf[:0]
+
+	_, err := ew.w.Write(out)
+	return err
+}
+
+// Close flushes buffered data and writes the sentinel and HMAC trailer. It is idempotent.
+func (ew *encryptWriter) Close() error {
+	if ew.closed {
+		return ew.err
+	}
+	ew.closed = true
+
+	if ew.err != nil {
+		return ew.err
+	}
+
+	if err := ew.writeHeader(); err != nil {
+		ew.err = err
+		return err
+	}
+
+	if err := ew.flushChunk(); err != nil {
+		ew.err = err
+		return err
+	}
+
+	trailer := make([]byte, lengthSize, lengthSize+macSize)
+	trailer = ew.mac.Sum(trailer)
+
+	if _, err := ew.w.Write(trailer); err != nil {
+		ew.err = err
+		return err
+	}
+
+	return nil
+}
+
+// DecryptReader returns a Reader that decrypts a stream produced by EncryptWriter.
+// The stream is read lazily: header, format and integrity errors are returned from Read.
+func DecryptReader(r io.Reader, key []byte) (io.Reader, error) {
+	aead, err := newAEAD(key)
+	if err != nil {
+		return nil, err
+	}
+
+	k := make([]byte, len(key))
+	copy(k, key)
+
+	return &decryptReader{
+		r:    r,
+		aead: aead,
+		mac:  hmac.New(sha256.New, k),
+	}, nil
+}
+
+type decryptReader struct {
+	r           io.Reader
+	aead        cipher.AEAD
+	mac         hash.Hash
+	initialized bool
+	plain       []byte
+	done        bool
+	err         error
+}
+
+func (dr *decryptReader) Read(p []byte) (int, error) {
+	if len(p) == 0 {
+		return 0, nil
+	}
+
+	for len(dr.plain) == 0 {
+		if dr.err != nil {
+			return 0, dr.err
+		}
+		if dr.done {
+			return 0, io.EOF
+		}
+
+		if err := dr.next(); err != nil {
+			dr.err = err
+		}
+	}
+
+	n := copy(p, dr.plain)
+	dr.plain = dr.plain[n:]
+	return n, nil
+}
+
+func (dr *decryptReader) readHeader() error {
+	header := make([]byte, headerSize)
+	if _, err := io.ReadFull(dr.r, header); err != nil {
+		return fmt.Errorf("encryption: invalid header: %w", unexpectedEOF(err))
+	}
+
+	if header[0] != magic[0] || header[1] != magic[1] {
+		return errors.New("encryption: invalid header: bad magic bytes")
+	}
+
+	if header[2] != Version {
+		return fmt.Errorf("encryption: unsupported version %d", header[2])
+	}
+
+	return nil
+}
+
+// next reads and decrypts the next chunk, or verifies the trailer when the sentinel is reached.
+func (dr *decryptReader) next() error {
+	if !dr.initialized {
+		dr.initialized = true
+		if err := dr.readHeader(); err != nil {
+			return err
+		}
+	}
+
+	lenBuf := make([]byte, lengthSize)
+	if _, err := io.ReadFull(dr.r, lenBuf); err != nil {
+		return fmt.Errorf("encryption: truncated stream: %w", unexpectedEOF(err))
+	}
+
+	chunkLen := binary.BigEndian.Uint32(lenBuf)
+	if chunkLen == 0 {
+		return dr.verifyTrailer()
+	}
+
+	if chunkLen < minChunkLen || chunkLen > maxChunkLen {
+		return fmt.Errorf("encryption: invalid chunk length %d", chunkLen)
+	}
+
+	chunk := make([]byte, chunkLen)
+	if _, err := io.ReadFull(dr.r, chunk); err != nil {
+		return fmt.Errorf("encryption: truncated stream: %w", unexpectedEOF(err))
